// A contact list that was rendered once keeps a blank row in the data, so its length says
// nothing about whether the record has contacts - look at what the rows contain.
const contacts = _.get(data, 'contacts', []);

const contactIsNotEmpty = (contact) => {
    return !!contact && (!!contact.contactFio ||
        !!contact.contactDepartment ||
        !!contact.contactEmail ||
        !!contact.contactPhone ||
        !!contact.contactPosition ||
        !!contact.contactComment);
};

const hasOwnContacts = contacts.some(contactIsNotEmpty);

value = hasOwnContacts;

// Scope the lookup to this form: the dialog and the dashlet are separate instances. A form that
// has been replaced keeps its markup in a detached tree, and working on that tree changes
// nothing the user sees, so such an instance falls back to the live document.
const isViewMode = !!_.get(instance, 'root.options.viewAsHtml');
const rootElement = _.get(instance, 'root.element');
const formRoot = (rootElement && document.contains(rootElement)) ? rootElement : document;

// The counterparty contacts arrive asynchronously. Until that request resolves the form knows
// nothing about them, so the placeholder has to stay hidden - otherwise every deal whose
// contacts live on the counterparty claims "there are no contacts" for the first seconds.
const counterpartyLoaded = !_.isUndefined(_.get(data, 'asyncCounterparty'));
const noContactsAtAll = !hasOwnContacts && !_.get(data, 'asyncCounterparty.contacts.length');

const placeholderElement = formRoot.querySelector('.citeck-contacts-widget_placeholder');
if (placeholderElement) {
  const htmlPlaceholder = placeholderElement.parentElement;

  if (htmlPlaceholder) {
    if (counterpartyLoaded && noContactsAtAll) {
      htmlPlaceholder.removeAttribute('hidden');
      htmlPlaceholder.removeAttribute('style');
    } else {
      htmlPlaceholder.setAttribute('hidden', true);
    }
  }
}

// Deferred by a tick: the conditions that decide which lists are shown are applied after this
// script runs, so looking at the markup right away finds the lists still hidden. Each list
// marks its first card as the one to open, and several lists can be on screen at once.
setTimeout(function () {
  const contactGrids = formRoot.querySelectorAll('.citeck-widget-contacts .formio-component-datagrid');

  for (let g = 0; g < contactGrids.length; g++) {
    const grid = contactGrids[g];

    if (grid.hasAttribute('hidden') || grid.closest('[hidden]')) {
      continue;
    }

    const cards = grid.querySelectorAll('.citeck-widget-contacts__not-collapsed');
    for (let i = 0; i < cards.length; i++) {
      const card = cards[i];

      if (card.closest('[hidden]')) {
        continue;
      }

      // An empty list still renders one blank row. While reading the record that row is a
      // column of dashes, so it stays shut; in the dialog it is the form for the first contact
      // and has to be open.
      const cardTitle = card.querySelector('.card-title');
      if (isViewMode && (!cardTitle || !cardTitle.textContent.trim())) {
        continue;
      }

      const cardBody = card.querySelector('.panel-body');
      if (!cardBody) {
        continue;
      }

      cardBody.removeAttribute('hidden');
      cardBody.removeAttribute('style');

      const iconElement = card.querySelector('.citeck-panel-icon-chevron');
      if (iconElement) {
        iconElement.className = "citeck-panel-icon-chevron down";
      }

      break;
    }
  }
}, 0);

