<style>
    .citeck-widget-contacts .form-group {
        margin: 0;
    }

    /* The platform sets a border and 0.65rem/0.5rem padding on every datagrid cell. Here each
       cell holds a whole contact card, so the cell must not add any frame of its own. The
       selector has to stay inside .citeck-widget-contacts and outrank
       `.formio-component-datagrid table.table-bordered td`, otherwise it either leaks onto
       every table of the page or loses and does nothing. */
    .citeck-widget-contacts .formio-component-datagrid table.table-bordered th,
    .citeck-widget-contacts .formio-component-datagrid table.table-bordered td {
        padding: 0 0 16px;
        border: none;
        height: auto;
    }

    /* The gap belongs between the cards, not after the last one - otherwise a widget of
       collapsed cards ends with an empty strip as tall as a card. */
    .citeck-widget-contacts .formio-component-datagrid table.table-bordered tr:last-child > td {
        padding-bottom: 0;
    }

    /* Direct child, not descendant: a contact card sits inside a wrapper panel, so a descendant
       selector applied this inset twice and squeezed the content into the middle of the widget.
       The card adds no inset of its own, so the fields line up with the neighbouring
       dashlets, which rely on the dashlet padding alone. */
    /* The step below the title belongs to the body, not to the title: a collapsed body is
       display:none, so its margin disappears with it and collapsed cards do not reserve room
       for content they are not showing. */
    .citeck-widget-contacts .card > .card-header {
        padding-bottom: 0;
    }

    .citeck-widget-contacts .card > .card-body.panel-body {
        padding: 0 !important;
        margin-top: 11px;
        margin-bottom: 0;
        /* the rows carry their own 5px above and below; the platform puts a 1rem flex gap on a
           datagrid panel body, which pushed the comment 16px away while the fields sat 10px
           apart - !important because that rule outranks this one */
        gap: 0 !important;
    }

    /* Only the read-only rows. While a field is being edited inline, the very same dl becomes
       the editor and carries `formio-component`; squeezing its sides to zero and dropping its
       bottom border left the label against the frame and the frame unfinished. */
    .citeck-widget-contacts-comment_view-mode,
    .citeck-widget-contacts-columns dl:not(.formio-component) {
        border-bottom: none !important;
        padding: 5px 0 !important;
    }

    .citeck-widget-contacts-comment_view-mode dd,
    .citeck-widget-contacts-columns dd {
        color: #444444;
        font-weight: 600;
    }

    .citeck-widget-contacts-comment_view-mode dt,
    .citeck-widget-contacts-columns dt {
        color: #B7B7B7;
    }
    .citeck-widget-contacts-comment_view-mode dt:after,
    .citeck-widget-contacts-columns dt:after {
        content: ":";
    }

    /* Keep the platform's title chip (`.formio-form .card .card-title`) - with several contacts
       in one widget it is the only thing separating one card from the next. Only the vertical
       rhythm and the icon alignment are adjusted here. */
    .citeck-widget-contacts .card .card-title {
        margin-top: 2px;
        margin-bottom: 0 !important;
        margin-left: 0;
        font-size: 14px !important;

        display: flex;
        gap: 3px;
        align-items: center;
    }

    /* The row-removal button lives in a column of its own. Left alone it is taller and wider
       than the title chip beside it, so it hangs above the chip and shortens every card that
       can be removed - which is why cards with and without it did not line up. */
    .citeck-widget-contacts .formio-remove-column {
        width: 40px;
        padding-left: 8px !important;
    }

    /* The platform sizes this button to the height of a form input (40px) so that it lines up
       with the fields of a normal data grid. Here it stands next to the 30px title chip, so it
       has to match the chip instead. The platform selector is repeated with the widget class in
       front of it, otherwise its four classes and three elements win. */
    .citeck-widget-contacts .formio-component-datagrid table.table-bordered
    td.formio-remove-column button.formio-button-remove-row {
        width: 32px;
        height: 30px;
        padding: 0;
        margin-top: 2px;
    }

    /* In the dialog the card is a framed box and its contents must sit inside the frame. In
       read-only mode the card has no frame and the fields line up with the neighbouring
       dashlets, so the inset is added only where a frame exists. */
    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts__not-collapsed > .card-body.panel-body {
        padding: 0 12px !important;
    }

    /* The heading sits in the card header and the fields in the card body, so both need the
       same inset - otherwise the title chip is 12px wider than the fields under it. */
    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts__not-collapsed > .card-header {
        padding-left: 12px;
        padding-right: 12px;
    }

    /* `.form-group { margin: 0 }` above is right for the read-only rows, but in the dialog it
       leaves 3px between a field and the label of the next one. */
    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts-columns .formio-component,
    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts-comment {
        margin-top: 12px;
    }

    /* The platform positions a checkbox absolutely and pulls it 20px out of the flow, so it
       hangs to the left of the column instead of starting where the fields start. Padding the
       label by the same 20px puts the box back on the column edge and the text after it. */
    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts .formio-component-contactMain label {
        padding-left: 20px;
    }

    /* The button that adds a contact otherwise touches the left and the bottom of the frame. */
    .formio-form:not(.formio-form_view-mode) .citeck-widget-contacts .formio-component-datagrid .btn-primary {
        margin: 4px 0 8px 12px;
    }
</style>

