        !!contact.contactPhone ||
        !!contact.contactPosition ||
        !!contact.contactComment);
};

const hasOwnContacts = contacts.some(contactIsNotEmpty);

for (const contact of contacts) {
  if (contact.contactMain) {
    checkMainContact = true;
    break;
  }
}

if (checkMainContact && contacts.length && !contacts[0].contactMain) {
  const sortedContacts = contacts;
  sortedContacts.sort((a, b) => b.contactMain - a.contactMain);
  var dataGridInst = util.searchComponents(instance.parent.components, "contacts");
  dataGridInst[0].setValue(sortedContacts);
}

